"""Texts generated by the integration itself (states and attribute lines).

Entity names and the config flow are translated by Home Assistant from
``translations/*.json``. Free-text states such as "Mon 30.11: 07:05–10:35 (4)"
are built in code, so they are localised here: Polish when Home Assistant
runs in Polish, English otherwise. Data scraped from mobiDziennik (subjects,
topics, remarks) is shown as is.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Texts:
    weekdays: tuple[str, ...]
    day_off: str  # "Day off – {reason}"
    no_lessons: str
    no_test: str
    room: str  # " (room {room})" for numeric rooms
    substitution: str  # " – substitute: {teacher}"
    weight: str  # "weight {weight}"
    unexcused: str  # "{count} unexcused"
    excused: str
    calendar_kinds: dict[str, str]


EN = Texts(
    weekdays=("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"),
    day_off="Day off – {reason}",
    no_lessons="No lessons",
    no_test="None",
    room=" (room {room})",
    substitution=" – substitute: {teacher}",
    weight="weight {weight}",
    unexcused="{count} unexcused",
    excused="excused",
    calendar_kinds={
        "test": "Test",
        "quiz": "Quiz",
        "trip": "Trip",
        "event": "Event",
        "info": "Info",
        "duty": "Duty",
        "own": "Note",
        "school": "School",
        "day_off": "Day off",
    },
)

PL = Texts(
    weekdays=("pon.", "wt.", "śr.", "czw.", "pt.", "sob.", "niedz."),
    day_off="Dzień wolny – {reason}",
    no_lessons="Brak lekcji",
    no_test="Brak",
    room=" (s. {room})",
    substitution=" – zastępstwo: {teacher}",
    weight="waga {weight}",
    unexcused="{count} nieuspr.",
    excused="uspr.",
    calendar_kinds={
        "test": "Sprawdzian",
        "quiz": "Kartkówka",
        "trip": "Wycieczka",
        "event": "Wydarzenie",
        "info": "Informacja",
        "duty": "Dyżur",
        "own": "Notatka",
        "school": "Szkoła",
        "day_off": "Dzień wolny",
    },
)

_current: Texts = EN


def set_language(language: str | None) -> Texts:
    """Select the texts for Home Assistant's language ("pl", "pl-PL", ...)."""
    global _current
    _current = PL if (language or "").lower().startswith("pl") else EN
    return _current


def current() -> Texts:
    return _current
